import {seaScore} from './adventure.mjs';
export const WORLD={left:-78,right:78,south:70,north:-292};
export const COURSE_VERSION='crocodile-v2';
export const RACE_POINTS=[{x:52,z:-6},{x:63,z:-30},{x:49,z:-55},{x:62,z:-79},{x:47,z:-104},{x:62,z:-129},{x:48,z:-155},{x:60,z:-182},{x:41,z:-213},{x:5,z:-239}];
export const CROCS=[{x:56,z:-44,phase:0},{x:54,z:-93,phase:2},{x:56,z:-143,phase:4},{x:48,z:-200,phase:1}];
export const RACE_START=RACE_POINTS[0],RACE_FINISH=RACE_POINTS.at(-1);
export function coastAt(z,side){return side*(78+Math.sin(z*.039)*5+Math.sin(z*.09)*2.5);}
export function channelAt(z){for(let i=0;i<RACE_POINTS.length-1;i++){const a=RACE_POINTS[i],b=RACE_POINTS[i+1];if(z<=a.z&&z>=b.z){const t=(z-a.z)/(b.z-a.z);return a.x+(b.x-a.x)*t;}}return z>RACE_START.z?RACE_START.x:RACE_FINISH.x;}
export const SHORTCUT=[RACE_POINTS[3],{x:69,z:-104},{x:69,z:-129},RACE_POINTS[6]];
export const ROCKS=[{x:59,z:-69},{x:70,z:-115},{x:50,z:-172}];
export const JELLIES=[{x:62,z:-35},{x:68,z:-96},{x:70,z:-139},{x:39,z:-216}];
export function shortcutAt(z){for(let i=0;i<SHORTCUT.length-1;i++){const a=SHORTCUT[i],b=SHORTCUT[i+1];if(z<=a.z&&z>=b.z)return a.x+(b.x-a.x)*(z-a.z)/(b.z-a.z);}return null;}
export function raceIntervals(z){const mid=channelAt(z),out=[[mid-5.8,mid+5.8]],short=shortcutAt(z);if(short!==null){out.push([short-2.65,short+2.65]);out.sort((a,b)=>a[0]-b[0]);if(out[1][0]<=out[0][1])return [[out[0][0],Math.max(out[0][1],out[1][1])]];}return out;}
export function raceBanksAt(z){return raceIntervals(z).flatMap(([l,r])=>[l-1.5,r+1.5]);}
export function gateTargets(i){return [RACE_POINTS[i],...(i===4?[SHORTCUT[1]]:i===5?[SHORTCUT[2]]:[])];}
export const EXTRA_BOOSTS=[{x:65.6,z:-92},{x:69,z:-117}];
export function crocodileAt(c,time){return {x:c.x+Math.sin(time*.8+c.phase)*2.8,z:c.z};}
export function freshRace(){return {x:RACE_START.x,z:RACE_START.z,heading:Math.PI,vx:0,vz:0,ticks:0,checkpoint:1,penalties:0,cooldown:0,finished:false,boost:120,slow:0,boosts:1,extraBoosts:[],route:'normal'};}
export function tickRace(s,command){if(s.finished)return s;const dt=1/60;const throttle=Math.max(-.4,Math.min(1,Number(command[0])||0));const turn=Math.max(-1,Math.min(1,Number(command[1])||0));const drift=command[2]===1;const target=command[3];if(Number.isFinite(target)){const delta=Math.atan2(Math.sin(target-s.heading),Math.cos(target-s.heading));s.heading+=Math.max(-(drift?4.3:2.5)*dt,Math.min((drift?4.3:2.5)*dt,delta));}else s.heading+=turn*dt*(drift?3.5:1.9)*(.35+Math.min(1,Math.hypot(s.vx,s.vz)/4));const grip=1-Math.exp(-(drift?1.1:4.4)*dt);const maxSpeed=(s.boost>0?21:12)*(s.slow>0?.52:1);s.vx+=(Math.sin(s.heading)*throttle*maxSpeed-s.vx)*grip;s.vz+=(Math.cos(s.heading)*throttle*maxSpeed-s.vz)*grip;s.x+=s.vx*dt;s.z+=s.vz*dt;
 const spans=raceIntervals(s.z);if(!spans.some(([a,b])=>s.x>=a&&s.x<=b)){const edge=spans.flat().reduce((a,b)=>Math.abs(b-s.x)<Math.abs(a-s.x)?b:a);s.x=edge;s.vx*=-.2;}s.z=Math.min(RACE_START.z+4,s.z);if(s.cooldown>0)s.cooldown--;if(s.boost>0)s.boost--;if(s.slow>0)s.slow--;
 for(const c of [...CROCS,{x:69,z:-124,phase:3}]){const p=crocodileAt(c,s.ticks/60);if(!s.cooldown&&Math.hypot(s.x-p.x,s.z-p.z)<2){s.vx*=.12;s.vz*=.12;s.penalties++;s.cooldown=90;s.slow=36;s.hit='croc';}}
 for(const p of ROCKS){const dx=s.x-p.x,dz=s.z-p.z,d=Math.hypot(dx,dz);if(!s.cooldown&&d<1.9){s.x=p.x+(dx||.01)/(d||.01)*2;s.z=p.z+dz/(d||.01)*2;s.vx*=-.5;s.vz*=-.5;s.cooldown=60;s.penalties++;s.hit='rock';}}
 for(const p of JELLIES)if(!s.cooldown&&Math.hypot(s.x-p.x,s.z-p.z)<1.4){s.slow=120;s.cooldown=120;s.penalties++;s.hit='jelly';}
 for(let i=0;i<EXTRA_BOOSTS.length;i++){const p=EXTRA_BOOSTS[i];if(!s.extraBoosts.includes(i)&&Math.hypot(s.x-p.x,s.z-p.z)<2.5){s.extraBoosts.push(i);s.boost=120;s.boosts++;}}
 const targets=gateTargets(s.checkpoint);const targetIndex=targets.findIndex((p,i)=>p&&Math.hypot(s.x-p.x,s.z-p.z)<(i?3.1:6.3));if(targetIndex>=0){if(targetIndex===1)s.route='shortcut';s.checkpoint++;s.boost=120;s.boosts++;if(s.checkpoint===RACE_POINTS.length)s.finished=true;}s.ticks++;return s;
}
export function replayRace(commands){if(!Array.isArray(commands)||commands.length<60||commands.length>18000)return {valid:false};const s=freshRace();for(const c of commands){if(!Array.isArray(c)||c.length!==4||!c.slice(0,3).every(Number.isFinite)||(c[3]!==null&&!Number.isFinite(c[3])))return {valid:false};tickRace(s,c);}return {valid:s.finished,timeMs:Math.round(s.ticks/60*1000),penalties:s.penalties,ticks:s.ticks};}
export function timeLabel(ms){const seconds=ms/1000;return `${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toFixed(2).padStart(5,'0')}`;}
export const ACHIEVEMENTS=[
 ['first-buoy','Primera BOIA','First BOIA','Descubre tu primera boya','Discover your first buoy',20],['all-buoys','Todas las frecuencias','Every frequency','Encuentra las seis boyas','Find all six buoys',40],['find-halloween','La isla embrujada','The haunted island','Visita Halloween','Visit Halloween',20],['find-christmas','Navidad a la deriva','Christmas adrift','Visita Navidad','Visit Christmas',20],['find-newyear','El último baile','The last dance','Visita Nochevieja','Visit New Year’s Eve',20],['all-islands','Todo el archipiélago','The whole archipelago','Visita las tres islas','Visit all three islands',40],['rescue','Nadie se queda atrás','No one left behind','Ayuda al náufrago','Help the castaway',30],['treasure','No todo es oro','Not all treasure is gold','Encuentra el tesoro','Find the treasure',30],['find-history','Nuestro origen','Our origin','Descubre la filosofía BOIA','Discover the BOIA philosophy',20],['find-music','Sintoniza el mar','Tune into the sea','Encuentra Radio BOIA','Find BOIA Radio',20],['find-fiestera','La mejor compañía','The best company','Encuentra la BOIA fiestera','Find the party BOIA',20],['find-gallery','Lo que vivimos','What we lived','Visita el puerto de recuerdos','Visit memory harbour',20],['find-whatsapp','Encuentra tu tripulación','Find your crew','Visita la boya de comunidad','Visit the community buoy',20],['find-shop','Un pedazo de BOIA','A little piece of BOIA','Visita la tienda en el mar','Visit the shop at sea',20],['find-christmas-discount','Una señal de invierno','A winter signal','Encuentra la sorpresa de Navidad','Find the Christmas surprise',20],['find-newyear-discount','Un último regalo','One last gift','Encuentra la sorpresa de Nochevieja','Find the New Year surprise',20],['paint','A tu color','Your own colour','Cambia el color del casco','Change the hull colour',10],['equip-flag','Alza tu bandera','Raise your flag','Equipa una bandera','Equip a flag',10],['equip-trail','Deja tu rastro','Leave a trail','Equipa una estela','Equip a wake',10],['equip-model','Nueva embarcación','A new vessel','Equipa otro modelo','Equip another model',15],['equip-accessory','Con personalidad','With personality','Equipa un accesorio','Equip an accessory',10],['time-5','Cinco minutos al timón','Five minutes at the helm','Acumula 5 minutos navegando','Sail for 5 minutes',30],['time-20','Lobo de mar','Sea wolf','Acumula 20 minutos navegando','Sail for 20 minutes',50],['first-race','La ruta del cocodrilo','The crocodile run','Termina tu primera carrera','Finish your first race',40],['rescue-fiestera','¡A bordo, Fiestera!','All aboard, Fiestera!','Rescata a la BOIA fiestera','Rescue the party BOIA',40],['deliver-fiestera','La fiesta nos esperaba','The party was waiting','Lleva a la Fiestera a Nochevieja','Take Fiestera to New Year’s Eve',70],['find-rare','Brilla el mar','The sea shines','Abre un cofre con un cosmético especial','Open a chest with a special cosmetic',30]
].map(([id,es,en,detailEs,detailEn,points])=>({id,es,en,detailEs,detailEn,points}));
export const REWARD_POINTS=Object.fromEntries([...ACHIEVEMENTS.map(a=>[a.id,a.points]),['survey',0],['bottle',0],['find-artists',20],['find-castaway',20],['find-treasure',20],['find-lighthouse',20],['find-race',20],['escort',30]]);
export const COSTS={flag:40,trail:60,model:90,accessory:50};
export function normalisePoints(p){p.rewards=[...new Set(p.rewards||[])].filter(id=>Object.hasOwn(REWARD_POINTS,id));p.points=p.rewards.reduce((sum,id)=>sum+REWARD_POINTS[id],0)+seaScore(p.seaLedger);p.owned=[...new Set(p.owned||[])].filter(id=>Object.hasOwn(COSTS,id));p.coins=Math.max(0,p.points-p.owned.reduce((sum,id)=>sum+(id==='accessory'&&p.rewards.includes('find-rare')?0:COSTS[id]),0));return p;}
